      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "Noscapine, a dimethoxy-substituted isoquinoline alkaloid, had absolute oral bioavailability of 30% (range 16–58%) in human volunteers, supporting F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Valbenazine, a dimethoxy-substituted tetrahydroisoquinoline drug, has absolute oral bioavailability of approximately 49% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C60"],
      "claim": "Levosulpiride absolute oral bioavailability was 23.4% in Chinese volunteers, supporting F≥20% despite incomplete absorption.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Query is ivabradine, a known If-channel inhibitor with reported oral bioavailability around 40%; analog evidence from verapamil, noscapine, valbenazine, and levosulpiride consistently supports F≥20%, with only occasional sub-20 values in related drugs. Prediction: high.",
